public class Main {
    static int choose(int mode, int[] data) {
        return switch (mode) {
            case 0 -> data[0];
            case 1 -> {
                int old = data[1];
                data[1] += data[0];
                yield old;
            }
            default -> data.length;
        };
    }
    public static void main(String[] args) {
        int[] a = {2, 5};
        int x = choose(1, a);
        int y = choose(0, a);
        System.out.print(x + ":" + y + ":" + a[1]);
    }
}

