public class Main {
    public static void main(String[] args) {
        int row = 0;
        int hits = 0;

        scan:
        while (row < 4) {
            row++;
            for (int col = 0; col < 4; col++) {
                if (col == row) {
                    continue scan;
                }
                hits++;
            }
        }
        System.out.print(row + ":" + hits);
    }
