        int sum = 0;
        outer:
        for (int i = 1; i <= 3; i++) {
            for (int j = 1; j <= 3; j++) {
                if (i * j >= 4) {
                    break outer;
                }
                sum += i * j;
            }
        }
        System.out.print(sum);
