interface Fly {
    String fly();
}
class Bird implements Fly {
    public String fly() { return "B"; }
}
class Stone { }

public class Main {
    public static void main(String[] args) {
        Object[] values = { new Bird(), new Stone() };
        int ok = 0;
        for (Object value : values) {
            try {
                Fly f = (Fly) value;
                System.out.print(f.fly());
                ok++;
            } catch (ClassCastException e) {
                System.out.print("X");
            }
        }
        System.out.print(":" + ok);
    }
}

